<?php require_once "../db.php";require_role("Student");$id=(int)($_GET["id"]??0);$st=$conn->prepare("SELECT * FROM practice_material WHERE id=?");$st->bind_param("i",$id);$st->execute();$m=$st->get_result()->fetch_assoc();if(!$m)die("Material not found.");
if($_SERVER["REQUEST_METHOD"]==="POST"){ $score=(int)$_POST["score"];$total=(int)$_POST["total_questions"];$attempt=(int)$_POST["attempted_questions"];$correct=(int)$_POST["correct_answers"];$wrong=(int)$_POST["wrong_answers"];$uid=current_id();$in=$conn->prepare("INSERT INTO practice_history(student_id,material_id,score,total_questions,attempted_questions,correct_answers,wrong_answers) VALUES(?,?,?,?,?,?,?)");$in->bind_param("iiiiiii",$uid,$id,$score,$total,$attempt,$correct,$wrong);$in->execute();go("practice_analysis.php?id=".$conn->insert_id);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($m["title"])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card"><div class="card-body p-5"><span class="badge bg-primary"><?=e($m["subject"])?></span><h2 class="fw-bold mt-3"><?=e($m["title"])?></h2><p class="lead text-muted"><?=e($m["description"])?></p><div class="bg-light rounded p-4 mb-4"><?=nl2br(e($m["content"]))?></div><h5>Record Practice Result</h5><form method="post"><div class="row g-3"><?php foreach(["total_questions"=>"Total Questions","score"=>"Score","attempted_questions"=>"Attempted","correct_answers"=>"Correct","wrong_answers"=>"Wrong"] as $name=>$label):?><div class="col-md-4"><label class="form-label"><?=$label?></label><input type="number" name="<?=$name?>" min="0" class="form-control" required></div><?php endforeach;?></div><button class="btn btn-success mt-4">Save Result</button></form></div></div></div></body></html>
